    21
    """
    type_name_to_class = {
        'int': int,
        'float': float,
        'bool': bool,
        'str': str,
    }

    if arg not in self.types:
        return value

    type_def = self.types[arg]

    # Resolve string type name to actual type object if necessary
    if isinstance(type_def, str):
        converter = type_name_to_class.get(type_def)
    else:
        converter = type_def

    if converter is None or not callable(converter):
        return value

    try:
        return converter(value)
    except (ValueError, TypeError):
        return value

